const API = '/api/handle/v1';
const AUDIT_SCOPES = ['audit.read', 'audit.propose', 'questions.create', 'relay.provision', 'context.read'];
const OPERATION_SCOPES = ['cases.quote', 'orders.checkout', 'inbox.claim', 'inbox.reply', 'registry.publish', 'website.agent-card.publish'];
const TABS = [['overview', 'Přehled'], ['audit', 'Audit a otázky'], ['rules', 'Pravidla'], ['agents', 'Agenti a přístupy'], ['website', 'Publikace webu'], ['handover', 'Předání firmy']];
const state = { owner: null, csrf: '', dashboard: { businesses: [], requests: [] }, businessId: '', tab: 'overview', authMode: 'login', busy: false };
const main = document.querySelector('#main');
const requestedId = new URLSearchParams(location.search).get('request');
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const list = value => Array.isArray(value) ? value : [];
function parsed(value, fallback = {}) { if (value && typeof value === 'object') return value; try { return JSON.parse(value) ?? fallback; } catch { return fallback; } }
const record = value => ({ ...parsed(value?.payload_json), ...parsed(value?.payload), ...value });
const business = () => list(state.dashboard.businesses).find(value => value.id === state.businessId);
const connectionScopes = value => list(value.scopes ?? parsed(value.scopes_json, []));
const readiness = value => parsed(value.ready ?? value.readiness ?? value.ready_json, null);
const activeRulebook = value => list(value?.rulebooks).map(record).find(rule => rule.status === 'active');
const currentPublication = value => value?.active_connection_id && activeRulebook(value) ? list(value.publications).find(item => ['published', 'verified'].includes(item.state) && item.rulebook_hash === activeRulebook(value).payload_hash) : undefined;
const reports = value => list(value?.reports).map(record).map(report => ({ ...report, answers: list(value?.answers).filter(answer => answer.report_version === report.version), evidence: list(value?.evidence).filter(source => list(report.systems).some(system => system.id === source.capture?.system_id)) })).sort((a, b) => b.version - a.version);
const latestReport = value => reports(value)[0];
const money = value => Number.isSafeInteger(value) ? new Intl.NumberFormat('cs-CZ', { style: 'currency', currency: 'CZK' }).format(value / 100) : 'Neuvedeno';
function evidenceImage(item) { const mime = item.capture?.content_type || item.content_type; return ['image/png', 'image/jpeg'].includes(mime) && typeof item.attachment_base64 === 'string' && /^[A-Za-z0-9+/=]+$/.test(item.attachment_base64) ? `<img class="evidence-image" src="data:${mime};base64,${item.attachment_base64}" alt="${esc(item.content || 'Redigovaný auditní důkaz')}">` : ''; }
const ownerPath = (value, path) => `/businesses/${encodeURIComponent(value.id)}/owner/${path}`;
const datetime = value => { const date = new Date(typeof value === 'number' && value < 1e12 ? value * 1000 : value); return Number.isNaN(date.getTime()) ? 'Neuvedeno' : date.toLocaleString('cs-CZ', { timeZone: 'Europe/Prague', dateStyle: 'medium', timeStyle: 'short' }); };
function safeUrl(value) { try { const url = new URL(value, location.origin); if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) return ''; for (const key of [...url.searchParams.keys()]) if (/token|secret|password|key|code|credential|session/i.test(key)) url.searchParams.set(key, '[skryto]'); return url.href; } catch { return ''; } }
function link(value, label = value) { const url = safeUrl(value); return url ? `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>` : esc(label || 'Neuvedeno'); }
const labels = { active: 'Aktivní', proposed: 'Návrh', superseded: 'Nahrazeno', audit_only: 'Pouze audit', pending: 'Čeká', approved: 'Schváleno', rejected: 'Zamítnuto', revoked: 'Odvoláno', suspended: 'Pozastaveno', ready: 'Připraveno', prepared: 'Připraveno k potvrzení', committed: 'Předáno', published: 'Veřejně ověřeno', verified: 'Ověření zaznamenáno', withdrawal_pending: 'Stažení čeká na ověření', external_access_revocation_pending: 'Čeká na externí odvolání', pending_external_revocation: 'Čeká na externí odvolání', pending_reconciliation: 'Čeká na dohledání zápisu', verified_revoked: 'Odvolání ověřeno', controlled_native: 'Nativně řízený přístup', revocation_pending: 'Odvolání neověřeno', uncertain_write: 'Nejistý zápis' };
function chip(value) { const good = ['active', 'approved', 'ready', 'published', 'verified', 'committed', 'verified_revoked'].includes(value); const bad = ['revoked', 'rejected', 'suspended', 'failed'].includes(value); return `<span class="chip ${good ? 'ok' : bad ? 'bad' : 'wait'}">${esc(labels[value] || value || 'Neověřeno')}</span>`; }
function fields(entries) { return `<dl class="metadata">${entries.map(([key, value]) => `<dt>${esc(key)}</dt><dd>${value ?? 'Neuvedeno'}</dd>`).join('')}</dl>`; }
function scopes(values) { return `<div class="scopes">${list(values).map(scope => `<span class="scope">${esc(scope)}</span>`).join('') || '<span class="small mute">Bez oprávnění</span>'}</div>`; }
function scopeChoices(values, selected = []) { return `<div class="scope-choices">${values.map(scope => `<label class="check"><input type="checkbox" name="scopes" value="${esc(scope)}" ${selected.includes(scope) ? 'checked' : ''}><span class="code">${esc(scope)}</span></label>`).join('')}</div>`; }
function feedback(message, error = false) { const target = document.querySelector('#feedback'); target.textContent = message; target.classList.toggle('error', error); target.hidden = false; if (error) { target.setAttribute('role', 'alert'); target.scrollIntoView({ block: 'nearest' }); } else target.setAttribute('role', 'status'); }
async function api(path, body) {
  const response = await fetch(`${API}${path}`, { method: body === undefined ? 'GET' : 'POST', credentials: 'same-origin', redirect: 'error', headers: { Accept: 'application/json', ...(body === undefined ? {} : { 'Content-Type': 'application/json', 'x-csrf-token': state.csrf }) }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    const code = data.error?.code || data.code || `HTTP_${response.status}`;
    const accountMessages = {
      OWNER_SETUP_REQUIRED: 'Aktivační kód chybí nebo není správný. Vložte soukromý kód pro založení prvního účtu.',
      OWNER_EXISTS: 'První účet už byl založen. Přepněte na „Přihlásit se“.',
      INVALID_LOGIN: 'Nesprávný e-mail nebo heslo.',
      INVALID_ACCOUNT: 'Zadejte platný e-mail a heslo dlouhé alespoň 12 znaků.',
    };
    const error = new Error(accountMessages[code] || `${code}: ${data.error?.message || data.message || (typeof data.error === 'string' ? data.error : 'Požadavek se nepodařil.')}`);
    error.status = response.status;
    throw error;
  }
  return data;
}
async function load() {
  main.setAttribute('aria-busy', 'true');
  try {
    const session = await api('/owner/session');
    state.owner = session.owner; state.csrf = session.csrf_token || '';
    if (!state.owner) { state.csrf = ''; render(); return; }
    state.dashboard = await api('/owner/dashboard');
    if (!business()) state.businessId = list(state.dashboard.businesses)[0]?.id || '';
    if (requestedId && !list(state.dashboard.requests).some(value => value.id === requestedId)) {
      const request = await api(`/owner/onboarding/${encodeURIComponent(requestedId)}`);
      state.dashboard.requests = [...list(state.dashboard.requests), request.request || request];
    }
    render();
  } catch (error) { if (error.status === 401) { state.owner = null; state.csrf = ''; render(); } else { render(); feedback(error.message, true); } }
  finally { main.setAttribute('aria-busy', 'false'); }
}
function renderNavigation() {
  document.querySelector('#navigation').innerHTML = state.owner ? TABS.map(([id, label], index) => `<button type="button" data-tab="${id}" ${state.tab === id ? 'aria-current="page"' : ''}><span class="nav-number">0${index + 1}</span>${label}</button>`).join('') : '<p class="small mute">Přihlaste se samostatným lidským účtem Handle.</p>';
  document.querySelector('#identity').innerHTML = state.owner ? `<span>${esc(state.owner.email)}</span><button class="btn btn-line btn-sm" type="button" data-action="refresh">Obnovit</button><button class="btn-q" type="button" data-action="logout">Odhlásit</button>` : '<span>Soukromá konzole</span>';
}
function render() {
  renderNavigation();
  if (!state.owner) { renderAuth(); return; }
  const value = business();
  const titles = { overview: ['Firma má kontext.', 'Od prvního připojení k provozu, který řídíte vy.'], audit: ['Nejdřív porozumět.', 'Důkazy, autority zdrojů a otázky před schválením pravidel.'], rules: ['Pravidla ve vašich rukou.', 'Aktivujete konkrétní verzi a hash; agent si souhlas neuděluje.'], agents: ['Každý agent, vlastní přístup.', 'Auditní připojení, ověřené schopnosti a odvolatelný provozní rozsah.'], website: ['Jeden veřejný kontakt.', 'Agent zveřejní kartu a odkaz až po vašem souhlasu.'], handover: ['Firma zůstává. Agent se mění.', 'Předání zachová kontext, případy a platné souhlasy.'] };
  main.innerHTML = `<div class="heading"><div><span class="eyebrow">${esc(value?.name || 'První den s Handle')}</span><h1>${titles[state.tab][0]}</h1><p>${titles[state.tab][1]}</p></div>${list(state.dashboard.businesses).length ? `<label class="field"><span class="lbl small">Firma</span><select class="input" id="business-select">${state.dashboard.businesses.map(item => `<option value="${esc(item.id)}" ${item.id === state.businessId ? 'selected' : ''}>${esc(item.name)}</option>`).join('')}</select></label>` : ''}</div><div class="stack">${state.tab === 'overview' ? renderOverview(value) : !value ? emptyBusiness() : state.tab === 'audit' ? renderAudit(value) : state.tab === 'rules' ? renderRules(value) : state.tab === 'agents' ? renderAgents(value) : state.tab === 'website' ? renderWebsite(value) : renderHandover(value)}</div>`;
}
function renderAuth() {
  const signup = state.authMode === 'signup';
  main.innerHTML = `<div class="auth-layout"><div class="auth-copy"><span class="eyebrow">Majitel má poslední slovo</span><h1>Váš business.<br>Vaše pravidla.</h1><p>GrokBot prozkoumá systémy a navrhne pravidla. Vy nezávisle potvrdíte připojení, posoudíte audit a povolíte přesný rozsah práce.</p><div class="note info">Přihlášení do Handle je oddělené od admin účtu Pneu, který jste předali agentovi.</div>${requestedId ? '<p class="small">Otevřeli jste žádost o připojení. Po přihlášení ji můžete zkontrolovat. Odkaz nic automaticky neschvaluje.</p>' : ''}</div><section class="surface auth-card" aria-label="Lidské přihlášení"><div class="auth-tabs"><button type="button" data-auth="login" aria-current="${!signup}">Přihlásit se</button><button type="button" data-auth="signup" aria-current="${signup}">První účet</button></div><form data-form="${signup ? 'signup' : 'login'}"><label class="field"><span class="lbl">E-mail</span><input class="input" name="email" type="email" autocomplete="username" required maxlength="200"></label><label class="field"><span class="lbl">${signup ? 'Nové heslo · nejméně 12 znaků' : 'Heslo'}</span><input class="input" name="password" type="password" autocomplete="${signup ? 'new-password' : 'current-password'}" ${signup ? 'minlength="12"' : ''} maxlength="200" required></label>${signup ? '<label class="field"><span class="lbl">Aktivační kód pro první účet</span><input class="input" name="setup_secret" type="text" autocomplete="one-time-code" inputmode="text" autocapitalize="none" autocorrect="off" spellcheck="false" maxlength="200" aria-describedby="owner-activation-help" required><span class="hint" id="owner-activation-help">Soukromý kód od provozovatele Handle. Slouží pouze k založení prvního účtu; není to vaše heslo.</span></label>' : ''}<button class="btn btn-green" type="submit">${signup ? 'Vytvořit účet' : 'Přihlásit do Handle'} →</button></form><p class="form-note">Heslo ani aktivační kód nepředávejte svému agentovi.</p></section></div>`;
}
function emptyBusiness() { return '<section class="surface"><h2>Firma ještě není připojena</h2><p>Dejte fresh botovi URL Handle a přístupy k legacy systémům bezpečným kanálem. Bot zahájí žádost a ukáže vám ověřovací kód.</p><p class="small mute">Účet, relay, audit ani pravidla se nepředvyplňují.</p></section>'; }
function pendingRequests() {
  const values = list(state.dashboard.requests).filter(value => value.state === 'pending' || value.id === requestedId);
  if (!values.length) return '';
  return `<section class="surface"><h2>Žádosti o připojení</h2><ul class="list">${values.map(value => `<li><div class="section-head"><h3>${esc(value.runtime || 'Nový agent')}</h3>${chip(value.state)}</div>${fields([['Žádost', `<span class="code">${esc(value.id || value.request_id)}</span>`], ['Legacy web', link(value.legacy_url)], ['Platnost', esc(datetime(value.expires_at))]])}${value.state === 'pending' ? `<form data-form="consent" data-request="${esc(value.id || value.request_id)}"><div class="note info">Porovnejte web a runtime s vaším agentem. Bot musí předem zveřejnit jednorázovou ownership challenge přes legacy admin; samotný kód vlastnictví firmy nedokazuje.</div><label class="field"><span class="lbl">Kód od vašeho agenta</span><input class="input code-input" name="user_code" inputmode="numeric" autocomplete="off" pattern="[0-9]{6}" maxlength="6" required placeholder="6 číslic"></label><fieldset class="fs"><legend>Povolit auditní a onboarding účely</legend>${scopeChoices(AUDIT_SCOPES, AUDIT_SCOPES)}</fieldset><label class="check"><input name="reviewed" type="checkbox" required><span>Ověřil/a jsem firmu a tohoto agenta. Souhlasím s vybranými účely. Tento krok nepovoluje nákupy ani publikaci.</span></label><div class="actions"><button class="btn btn-green" name="decision" value="approved" type="submit">Schválit připojení</button><button class="btn btn-line" name="decision" value="rejected" type="submit" formnovalidate>Zamítnout</button></div></form>` : ''}</li>`).join('')}</ul></section>`;
}
function renderOverview(value) {
  const pending = pendingRequests();
  if (!value) return pending + emptyBusiness();
  const rule = activeRulebook(value), report = latestReport(value), relay = value.relay, published = Boolean(currentPublication(value));
  const completed = [true, Boolean(relay), Boolean(report), Boolean(rule), published];
  const current = completed.indexOf(false);
  const stepNames = [['Připojení', 'Člověk potvrdí identitu.'], ['Relay', 'Agent vyžádá svůj inbox.'], ['Audit', 'Zdroje, fakta a neznámé.'], ['Pravidla', 'Přesná lidská aktivace.'], ['Publikace', 'Karta a odkaz na webu.']];
  const next = !relay ? ['Agent vyžádá relay', 'Onboarding connection může přes podporované API idempotentně vytvořit firemní relay. Majitel nezakládá hosting.', 'agents'] : !report ? ['Teď je na řadě audit', 'Agent prohlédne web, administrace a dostupná API/MCP. Žádné závěry se mu nepředvyplňují.', 'audit'] : !rule ? ['Posuďte audit a přesnou verzi', 'Zodpovězte neznámé, přezkoumejte autoritu důkazů a aktivujte konkrétní hash pravidel.', 'rules'] : !value.active_connection_id ? ['Povolte omezený provoz', 'Agent musí doložit schopnosti. Potom můžete povolit vybrané provozní nástroje.', 'agents'] : !published ? ['Agent zveřejní svůj kontakt', 'Zkontrolujte publication grant. Bot publikuje kartu a odkaz; Handle ověří skutečný stav.', 'website'] : ['Provoz pod kontrolou', 'Sledujte připojení a nevyřešené kroky. Platební a provozní systémy zůstávají zdrojem skutečných výsledků.', 'agents'];
  return `${pending}<ol class="flow" aria-label="Průchod prvním dnem">${stepNames.map(([name, detail], index) => `<li class="${completed[index] ? 'done' : index === current ? 'current' : ''}"><b>0${index + 1}</b><strong>${name}${completed[index] ? ' ✓' : ''}</strong><span>${detail}</span></li>`).join('')}</ol><section class="surface next"><span class="kicker">Nejbližší krok</span><h2>${next[0]}</h2><p>${next[1]}</p><div class="actions"><button class="btn btn-gold" data-tab="${next[2]}">Otevřít detail →</button></div></section><div class="kpis"><div class="kpi"><span class="qlab">Rulebook</span><strong>${rule ? `Verze ${esc(rule.version)}` : 'Neaktivní'}</strong><span class="d">${rule ? 'Přesná lidsky schválená pravidla' : 'Automatické závazky zůstávají zavřené'}</span></div><div class="kpi"><span class="qlab">Připojení</span><strong>${list(value.connections).filter(item => item.state !== 'revoked').length}</strong><span class="d">Execution epoch ${esc(value.execution_epoch)}</span></div><div class="kpi"><span class="qlab">Veřejná karta</span><strong>${published ? 'Aktuálně ověřená' : 'Čeká na ověření'}</strong><span class="d">${published ? 'Pro aktuální schválený rulebook a připojení' : 'Starší revize sama nedokládá aktuální dostupnost'}</span></div></div><section class="surface"><h2>Firemní kontext</h2>${fields([['Firma', `<span class="code">${esc(value.id)}</span>`], ['Web', link(value.legacy_url)], ['Aktivní agent', `<span class="code">${esc(value.active_connection_id || 'Žádný')}</span>`], ['Relay', relay ? link(relay.endpoint, 'Přidělený firemní endpoint') : 'Agent zatím nevyžádal relay']])}<p class="small mute">Interní kontext patří firmě. Secrets a lidské sessions se mezi agenty nepřenášejí.</p></section>`;
}
function citations(values) {
  return list(values).map(cite => `<div class="evidence"><span class="code">${esc(cite.source_id || cite.evidence_id)} · ${esc(cite.version || cite.native_revision || '')}</span>${cite.excerpt ? `<blockquote class="audit-quote">${esc(cite.excerpt)}</blockquote>` : ''}${cite.hash ? `<span class="hash">SHA-256 ${esc(cite.hash)}</span>` : ''}</div>`).join('');
}
function renderAudit(value) {
  const values = reports(value);
  if (!values.length) return '<section class="surface"><h2>Čeká se na agentův report</h2><p>Agent audituje běžná UI, dokumenty a existující API/MCP. Uloží systémový inventář, citace, přílohy a neznámé. Konektor pro audit není podmínkou.</p><div class="note info">Admin přístup může umožňovat zápisy. Audit zůstává pozorovací chováním agenta, nikoli automaticky serverově read-only.</div></section>';
  return `<div class="note info">Hash dokládá integritu archivu. Pravdivost, autoritu a živou aktuálnost zdroje posuzujete samostatně.</div>${values.map(report => `<section class="surface"><div class="section-head"><h2>Audit · verze ${esc(report.version)}</h2>${chip(report.status || 'proposed')}</div>${report.summary ? `<p>${esc(report.summary)}</p>` : ''}${report.payload_hash ? `<span class="hash">${esc(report.payload_hash)}</span>` : ''}${fields([['Pořízeno', esc(datetime(report.created_at))], ['Autor', `<span class="code">${esc(report.proposed_by || report.created_by || 'Agent')}</span>`]])}<div class="report-block"><h3>Inventář systémů</h3><ul class="list">${list(report.systems).map(system => `<li><strong>${esc(system.name || system.id || system.system_id)}</strong>${fields([['Systém', `<span class="code">${esc(system.id || system.system_id)}</span>`], ['URL', link(system.url)], ['Účel', esc(system.purpose || system.description)], ['Autorita', esc(typeof system.authority === 'string' ? system.authority : list(system.fact_authority || system.authority).join(', '))], ['Přístup', esc(system.access_method || system.method || list(system.access_methods || system.interfaces).join(', ') || 'Neuvedeno')]])}${scopes(system.supported_actions || system.capabilities)}</li>`).join('') || '<li class="mute">Inventář chybí; automatické cesty nelze předpokládat.</li>'}</ul></div>${list(report.processes).length ? `<div class="report-block"><h3>Pozorované procesy</h3><ul class="list">${report.processes.map(process => `<li><strong>${esc(process.id)}</strong><p>${esc(process.description)}</p>${citations(process.citations)}</li>`).join('')}</ul></div>` : ''}${list(report.findings).length ? `<div class="report-block"><h3>Závěry a rozpory</h3><ul class="list">${report.findings.map(finding => `<li><div class="badge-line"><span class="chip ${finding.severity === 'critical' ? 'bad' : finding.severity === 'warning' ? 'warn' : 'info'}">${esc(finding.severity || 'info')}</span><strong>${esc(finding.title || finding.id)}</strong></div><p>${esc(finding.description || finding.statement)}</p>${finding.recommendation ? `<p class="small mute">${esc(finding.recommendation)}</p>` : ''}${citations(finding.citations)}</li>`).join('')}</ul></div>` : ''}${list(report.supported_writes || report.supported_write_matrix || report.actions).length ? `<div class="report-block"><h3>Provozní cesty</h3><ul class="list">${list(report.supported_writes || report.supported_write_matrix || report.actions).map(action => `<li><strong>${esc(action.action || action.id || action.name)}</strong> ${chip(action.mode || action.status || 'unverified')}<p class="small">${esc(action.enforcement_path || action.path || action.description)}</p></li>`).join('')}</ul></div>` : ''}<div class="report-block"><h3>Otázky majiteli</h3><ul class="list">${list(report.questions).map(question => `<li><strong>${esc(question.question || question.text || question.description)}</strong>${question.critical ? '<p class="small error-text">Kritická neznámá · dotčená akce je blokovaná.</p>' : ''}${question.answer || list(report.answers).some(answer => answer.question_id === question.id) ? `<p class="audit-quote">${esc(typeof question.answer === 'string' ? question.answer : question.answer?.answer || list(report.answers).find(answer => answer.question_id === question.id)?.answer || 'Odpověď uložena')}</p>${list(report.answers).filter(answer => answer.question_id === question.id).map(answer => fields([['Povaha odpovědi', esc(answer.kind === 'policy_decision' ? 'Rozhodnutí o politice' : 'Tvrzení o externím faktu')], ['Rozsah', esc(answer.scope)], ['Vloženo', esc(datetime(answer.created_at))], ['Platí do', answer.valid_until ? esc(datetime(answer.valid_until)) : 'Bez uvedené expirace'], ['Lidský důkaz', `<span class="code">${esc(answer.evidence?.source_id || 'Neuvedeno')}</span>`]])).join('')}<p class="small mute">Odpověď je zdroj; aktivaci pravidel nenahrazuje.</p>` : `<form class="inline-form" data-form="answer" data-version="${esc(report.version)}" data-question="${esc(question.id || question.question_id)}"><label class="field"><span class="lbl">Vaše odpověď / rozhodnutí</span><textarea class="input" name="answer" required maxlength="8000" placeholder="Uveďte skutečnost, její rozsah a případné omezení."></textarea></label><label class="field"><span class="lbl">Povaha odpovědi</span><select class="input" name="kind" required><option value="policy_decision">Rozhodnutí o firemní politice</option><option value="external_fact">Tvrzení o externím faktu · ověřit v systému</option></select></label><label class="field"><span class="lbl">Rozsah platnosti</span><input class="input" name="scope" required maxlength="2000" placeholder="Např. běžné provozní dny, konkrétní služba a provozovna."></label><label class="field"><span class="lbl">Platí do · volitelné, váš místní čas</span><input class="input" name="valid_until" type="datetime-local"></label><div><button class="btn btn-green btn-sm">Uložit odpověď</button></div></form>`}</li>`).join('') || '<li class="mute">Žádné uložené otázky. Absence otázky sama nepotvrzuje úplnost auditu.</li>'}</ul></div><div class="report-block evidence"><h3>Důkazy a citace</h3>${list(report.evidence || report.sources).map(item => `<details><summary>${esc(item.source_id || item.evidence_id || item.id)} · ${esc(item.capture?.system_id || item.system_id || '')}</summary>${fields([['Zdroj', link(item.url || item.source_url)], ['Obrazovka', esc(item.capture?.locator || item.locator)], ['Metoda', esc(item.capture?.method || item.method)], ['Pořízeno', esc(datetime(item.capture?.captured_at || item.captured_at))], ['Nativní revize', esc(item.capture?.native_revision || item.native_revision || 'Neposkytuje')]])}${item.content || item.excerpt ? `<blockquote class="audit-quote">${esc(item.content || item.excerpt)}</blockquote>` : '<p class="small mute">Příloha není textová. Výklad obrázku vyžaduje lidský přezkum.</p>'}${evidenceImage(item)}${item.hash ? `<span class="hash">SHA-256 ${esc(item.hash)}</span>` : ''}</details>`).join('') || '<p class="small mute">Přílohy nejsou součástí tohoto přehledu. Zkontrolujte citace u konkrétního pravidla.</p>'}</div></section>`).join('')}`;
}
function renderRules(value) {
  const values = list(value.rulebooks).map(record).sort((a, b) => b.version - a.version), active = activeRulebook(value);
  if (!values.length) return '<section class="surface"><h2>Žádný návrh pravidel</h2><p>Nechte agenta dokončit audit a vytvořit doložený návrh. Formulář nevytváří pravidla za něj.</p></section>' + renderApprovals(value);
  return values.map(rule => { const params = rule.params || {}; const keys = [...new Set([...Object.keys(active?.params || {}), ...Object.keys(params)])]; const report = reports(value).find(item => item.version === rule.governance?.report_version); const blocked = list(rule.governance?.blocked_parameters).length > 0 || list(report?.questions).some(question => question.critical && !question.answer && !list(report?.answers).some(answer => answer.question_id === question.id)); return `<section class="surface"><div class="section-head"><h2>Rulebook · verze ${esc(rule.version)}</h2>${chip(rule.status)}</div><p>${esc(rule.profile?.summary || '')}</p><span class="hash">Přesný payload hash: ${esc(rule.payload_hash || 'Chybí · nelze aktivovat')}</span><div class="table-wrap"><table class="comparison"><caption class="small mute">${active && active.version !== rule.version ? `Porovnání s aktivní verzí ${esc(active.version)}` : 'Podporované provozní parametry'}</caption><thead><tr><th scope="col">Parametr</th>${active && active.version !== rule.version ? '<th scope="col">Aktivní</th>' : ''}<th scope="col">Tato verze</th></tr></thead><tbody>${keys.map(key => `<tr class="${active && JSON.stringify(active.params?.[key]) !== JSON.stringify(params[key]) ? 'changed' : ''}"><th scope="row"><span class="code">${esc(key)}</span></th>${active && active.version !== rule.version ? `<td>${esc(JSON.stringify(active.params?.[key]) ?? 'Neuvedeno')}</td>` : ''}<td>${esc(JSON.stringify(params[key]) ?? 'Neuvedeno')}</td></tr>`).join('')}</tbody></table></div><div class="report-block evidence"><h3>Podklady jednotlivých pravidel</h3>${Object.entries(rule.evidence || {}).map(([key, cites]) => `<details><summary>${esc(key)}</summary>${citations(cites)}</details>`).join('') || '<p class="small mute">Citace nejsou dostupné.</p>'}</div>${list(rule.findings).length ? `<div class="report-block"><h3>Nálezy</h3><ul class="list">${rule.findings.map(finding => `<li><strong>${esc(finding.severity)} · ${esc(finding.id)}</strong><p>${esc(finding.description)}</p><p class="small mute">${esc(finding.recommendation)}</p>${citations(finding.citations)}</li>`).join('')}</ul></div>` : ''}${rule.status === 'proposed' ? `<form data-form="activate" data-version="${esc(rule.version)}" data-hash="${esc(rule.payload_hash)}"><div class="note ${blocked ? 'warn' : 'info'}">${blocked ? 'Návrh obsahuje blokované parametry nebo kritickou nezodpovězenou otázku. Agent musí zpracovat odpověď a doložit aktualizovaný návrh.' : 'Aktivace potvrzuje tuto verzi a hash. Samostatné granty určují, co může konkrétní agent vykonávat.'}</div><label class="check"><input name="reviewed" type="checkbox" required><span>Přezkoumal/a jsem zdroje, jejich autoritu, aktuálnost, neznámé a přesné podmínky této verze.</span></label><div><button class="btn btn-green" ${blocked || !rule.payload_hash ? 'disabled' : ''}>Aktivovat verzi ${esc(rule.version)}</button></div></form>` : rule.activated_at ? `<p class="small mute">Aktivováno ${esc(datetime(rule.activated_at))} · ${esc(rule.activated_by)}</p>` : ''}</section>`; }).join('') + renderApprovals(value);
}
function renderApprovals(value) {
  const values = list(value.approvals);
  if (!values.length) return '';
  return `<section class="surface"><h2>Cenové výjimky</h2><p class="small mute">Schválení platí jen pro uloženou nabídku, verzi a rulebook. Zákaznický mandát schvaluje zákazník samostatně.</p><ul class="list">${values.map(approval => { const quote = approval.quote, expired = !quote || Date.parse(quote.expires_at) <= Date.now(); return `<li><div class="section-head"><h3>Nabídka ${esc(approval.quote_id)}</h3>${chip(approval.status)}</div>${fields([['Případ', `<span class="code">${esc(approval.case_id)}</span>`], ['Verze nabídky', esc(approval.quote_version)], ['Rulebook', esc(approval.rulebook_version)], ['Celková cena', quote ? money(quote.price?.total_minor) : 'BLOCKED · chybí přesná nabídka'], ['Sleva', quote && Number.isSafeInteger(quote.price?.discount_bps) ? `${quote.price.discount_bps / 100} %` : 'Viz uložené cenové podmínky'], ['Termín ID', `<span class="code">${esc(quote?.slot_id)}</span>`], ['Expirace', esc(datetime(quote?.expires_at))]])}<span class="hash">Quote hash: ${esc(approval.quote_hash)}</span>${quote ? `<details class="review"><summary>Přesné služby a cena</summary><pre>${esc(JSON.stringify(quote.price, null, 2))}</pre></details>` : ''}${approval.status === 'pending' ? `<form class="inline-form" data-form="approval" data-approval="${esc(approval.id)}"><label class="check"><input name="reviewed" type="checkbox" required><span>Přezkoumal/a jsem přesnou nabídku, služby, termín, cenu a její hash. Rozhoduji pouze tuto cenovou výjimku.</span></label>${expired ? '<p class="small mute">Nabídka chybí nebo vypršela. Nechte agenta vytvořit aktuální návrh.</p>' : ''}<div class="actions"><button class="btn btn-green btn-sm" name="decision" value="approved" ${expired ? 'disabled' : ''}>Schválit výjimku</button><button class="btn btn-line btn-sm" name="decision" value="rejected" ${expired ? 'disabled' : ''}>Zamítnout</button></div></form>` : ''}</li>`; }).join('')}</ul></section>`;
}
function renderAgents(value) {
  const rule = activeRulebook(value);
  return `<div class="note info">Runtime má vlastní servisní identitu. Legacy admin heslo neuděluje lidský Handle souhlas. MCP a HTTP používají stejné serverové kontroly.</div>${list(value.connections).map(connection => { const proof = readiness(connection), proofCurrent = proof?.probe_passed === true && proof.rulebook_hash === rule?.payload_hash, revoked = ['revoked', 'suspended'].includes(connection.state); return `<section class="surface"><div class="section-head"><h2>${esc(connection.runtime || 'Agent')}</h2>${chip(connection.state)}</div>${fields([['Connection', `<span class="code">${esc(connection.id)}</span>`], ['Principal', `<span class="code">${esc(connection.principal_id)}</span>`], ['Aktivní vykonavatel', connection.id === value.active_connection_id ? 'Ano' : 'Ne']])}<h3>Udělený rozsah</h3>${scopes(connectionScopes(connection))}<div class="note ${proofCurrent ? 'info' : 'warn'}">${proofCurrent ? 'Runtime uložil probe pro přesný aktivní rulebook. Zkontrolujte způsob dostupnosti a omezení; důkaz není příslib nepřetržité obsluhy.' : 'BLOCKED · chybí probe pro přesný aktivní rulebook. Starší capability důkaz po změně pravidel nestačí.'}</div>${proof ? fields([['Dostupnost', esc(proof.method || proof.availability || proof.availability_mode || proof.polling || proof.mode || 'Viz capability důkaz')], ['Ověřeno', esc(datetime(proof.verified_at || proof.at))], ['Transport', esc(proof.transport || proof.binding || 'Neuvedeno')], ['Kontext hash', `<span class="code">${esc(proof.context_hash || proof.rulebook_hash || 'Neuvedeno')}</span>`]]) + scopes(proof.capabilities || proof.supported_capabilities) : ''}${!revoked ? `<details class="review"><summary>Povolit provozní nástroje / publikaci</summary><form class="inline-form" data-form="grant" data-connection="${esc(connection.id)}"><p class="form-note">Vyberte jen potřebná oprávnění. Backend znovu ověří aktivní pravidla, schopnosti a execution epoch ${esc(value.execution_epoch)}. Předání A → B proveďte v samostatném review.</p>${scopeChoices(OPERATION_SCOPES, connectionScopes(connection).filter(scope => OPERATION_SCOPES.includes(scope)))}<label class="check"><input name="reviewed" type="checkbox" required><span>Povoluji vybrané nástroje tomuto agentovi v mezích aktivní verze ${esc(rule?.version || '—')} a jejích pravidel. Publikace smí měnit pouze Agent Card a přímý odkaz.</span></label><button class="btn btn-green btn-sm" ${!rule || !proofCurrent ? 'disabled' : ''}>Uložit provozní grant</button></form></details><details class="review"><summary>Odvolat toto připojení</summary><form class="inline-form" data-form="revoke" data-connection="${esc(connection.id)}"><p class="form-note">Handle odvolá své credentials a řízené operace. Samostatné účty a sessions v jiných systémech musíte skutečně odvolat či rotovat.</p><label class="check"><input name="reviewed" type="checkbox" required><span>Odvolat právě toto připojení. Rozumím, že externí přístup může dál zůstávat platný.</span></label><button class="btn btn-danger btn-sm">Odvolat připojení</button></form></details>` : '<p class="small mute">Odvolanému připojení se staré credentials neobnovují. Nový runtime potřebuje vlastní připojení a souhlas.</p>'}</section>`; }).join('') || '<section class="surface"><p>Žádné připojení.</p></section>'}`;
}
function renderWebsite(value) {
  const publications = list(value.publications), grant = list(value.connections).find(connection => connection.id === value.active_connection_id && connectionScopes(connection).includes('website.agent-card.publish'));
  return `<section class="surface"><h2>Agent publikuje, Handle ověřuje</h2><p>Na firemním webu musí být <span class="code">/.well-known/agent-card.json</span> a viditelný přímý odkaz „Pro agenty“. Endpoint zákazník zjistí až z aktuální karty.</p>${fields([['Pravidla', activeRulebook(value) ? `Aktivní verze ${esc(activeRulebook(value).version)}` : 'BLOCKED · bez lidské aktivace'], ['Publication grant', grant ? 'Udělen aktivnímu agentovi' : 'Chybí · povolíte jej v Agenti a přístupy'], ['Aktuální ověření', currentPublication(value) ? 'Zaznamenáno pro aktivní rulebook a connection' : 'BLOCKED / čeká · historické ověření nestačí'], ['Cílová URL', link(`${String(value.legacy_url || '').replace(/\/$/, '')}/.well-known/agent-card.json`)]])}<div class="note info">Konzole za agenta nic nepublikuje. Pneu používá omezenou nativní site operaci. U cizího webu potřebuje agent skutečně dostupnou správu webu; chybějící přístup je asistovaný krok nebo BLOCKED.</div><div class="actions"><button class="btn btn-line btn-sm" data-tab="agents">Zkontrolovat granty</button></div></section><section class="surface"><h2>Publikační revize</h2><ul class="list">${publications.map(item => `<li><div class="badge-line"><strong class="code">${esc(item.id)}</strong>${chip(item.state)}</div>${fields([['Poslední ověření', esc(datetime(item.verified_at))], ['Rulebook hash', `<span class="code">${esc(item.rulebook_hash || 'Neuvedeno · jen historický záznam')}</span>`], ['Descriptor hash', `<span class="code">${esc(item.descriptor_hash || item.payload_hash || 'Neuvedeno')}</span>`]])}${item.state === 'withdrawal_pending' ? '<div class="note warn">Handle již může blokovat provoz, ale odstranění statického souboru/CDN ještě není ověřené.</div>' : ''}</li>`).join('') || '<li class="empty">Agent zatím neuložil publikaci. Samotná aktivace pravidel kartu nezveřejňuje.</li>'}</ul></section>`;
}
function renderHandover(value) {
  const active = activeRulebook(value), candidates = list(value.connections).filter(connection => connection.id !== value.active_connection_id && !['revoked', 'suspended'].includes(connection.state));
  const governingReport = reports(value).find(report => report.version === active?.governance?.report_version) || latestReport(value);
  const externalSystems = list(governingReport?.systems).filter(system => list(system.observed_roles).some(role => !['public', 'anonymous', 'service_account'].includes(role)));
  const handoffs = list(value.handoffs);
  const operationalReview = `<section class="surface"><h2>Rozpracované případy a operace</h2>${Array.isArray(value.cases) ? `<ul class="list">${value.cases.map(item => `<li><strong class="code">${esc(item.id)}</strong> ${chip(item.status)}${fields([['Nabídka', `<span class="code">${esc(item.quote_id || '—')} / ${esc(item.quote_version || '—')}</span>`], ['Rulebook', esc(item.rulebook_version || '—')], ['Objednávka', `<span class="code">${esc(item.order_id || '—')}</span>`], ['Mandát', `<span class="code">${esc(item.mandate_id || '—')}</span>`], ['Platba', `<span class="code">${esc(item.payment_intent_id || item.payment_id || list(item.payment).map(payment => payment.intent_id).join(', ') || '—')}</span>`]])}${item.quote ? `<details class="review"><summary>Přesná nabídka / platební reference</summary><span class="hash">Quote hash: ${esc(item.quote_hash || 'Neuvedeno')}</span><p class="small">Cena ${money(item.quote.price?.total_minor)} · termín ID ${esc(item.quote.slot_id)} · platnost ${esc(datetime(item.quote.expires_at))}</p><pre>${esc(JSON.stringify(item.quote.price?.service_spec || {}, null, 2))}</pre>${list(item.payment).map(payment => `<p class="small"><span class="code">${esc(payment.intent_id)}</span> ${chip(payment.state)} · ${esc(payment.provider)} · provider ID ${esc(payment.provider_payment_id || 'Zatím není doložen')}</p>`).join('')}</details>` : ''}</li>`).join('') || '<li class="empty">Žádné uložené případy v tomto přehledu.</li>'}</ul>` : '<div class="note warn">Přehled případů není v této odpovědi dostupný. Bez ověření skutečných otevřených případů a plateb nepovažujte review za úplný.</div>'}${list(value.operations || value.pending_operations).length ? `<h3>Operace a jejich skutečný stav</h3><ul class="list">${list(value.operations || value.pending_operations).map(item => `<li><strong class="code">${esc(item.id)}</strong> ${chip(item.state || item.status)}<p class="small">${esc(item.kind)} · ${esc(item.order_id || item.result?.order_id || '')} · ${esc(item.payment_intent_id || '')}</p></li>`).join('')}</ul>` : ''}${list(value.payments || value.pending_payments).length ? `<h3>Platební evidence</h3><ul class="list">${list(value.payments || value.pending_payments).map(item => `<li><strong class="code">${esc(item.id)}</strong> ${chip(item.state || item.status)}${fields([['Objednávka', `<span class="code">${esc(item.order_id)}</span>`], ['Provider / síť', esc([item.provider, item.network].filter(Boolean).join(' / '))], ['Částka', money(item.amount_minor)]])}</li>`).join('')}</ul>` : ''}</section>`;
  const nativeRevocation = `<section class="surface"><h2>Odvolat původní legacy admin přístup</h2><p class="small mute">Pokud měl A heslo k Pneu owner/staff, Handle revoke jej neodhlásí z legacy. Následující lidský krok skutečně změní heslo vybraného účtu a zruší jeho sessions. Nové heslo předejte bezpečně jen oprávněnému člověku/novému runtime.</p><form data-form="legacy-revoke"><label class="field"><span class="lbl">Účet předaný původnímu agentovi</span><select class="input" name="username" required><option value="">Vyberte skutečný účet…</option><option value="owner">owner · legacy administrace Pneu</option><option value="staff">staff · legacy obsluha Pneu</option></select></label><label class="check"><input name="reviewed" type="checkbox" required><span>Vím, který účet A používal. Povoluji rotaci jeho hesla a zrušení všech legacy sessions tohoto účtu. Samostatná lidská Handle session zůstává oddělená.</span></label><div><button class="btn btn-danger btn-sm">Rotovat heslo a odhlásit legacy účet</button></div></form></section>`;
  return `<div class="note warn">Handle revokace nezruší externí admin sessions. Nejasný browser zápis se nejdřív dohledá; nepředává se jako nový pokus. Čekající platba pokračuje pod původní autorizací a IDs.</div>${operationalReview}${nativeRevocation}<section class="surface"><h2>Připravit předání A → B</h2>${value.active_connection_id && candidates.length && active ? `<form data-form="handover"><div class="form-grid"><label class="field"><span class="lbl">A · současný vykonavatel</span><input class="input code-input" value="${esc(value.active_connection_id)}" readonly></label><label class="field"><span class="lbl">B · nový runtime</span><select class="input" name="target_connection_id" required><option value="">Vyberte připojení…</option>${candidates.map(connection => `<option value="${esc(connection.id)}">${esc(connection.runtime)} · ${esc(connection.id)}${readiness(connection) ? '' : ' · capability proof chybí'}</option>`).join('')}</select></label></div>${fields([['Execution epoch', esc(value.execution_epoch)], ['Aktivní rulebook', `Verze ${esc(active.version)}`]])}<span class="hash">${esc(active.payload_hash)}</span><p class="form-note">Review musí zahrnout případy, nabídky, souhlasy, platby a nejisté operace z firemního kontextu. B nesmí dostat tokeny, hesla ani lidskou session A.</p><h3>Přístupy podle auditu aktivních pravidel</h3><div class="external-review">${externalSystems.map((system, index) => `<fieldset data-external-system="${esc(system.id || system.system_id)}"><legend>${esc(system.name || system.id || system.system_id)}</legend><label class="field"><span class="lbl">Skutečný stav odvolání / zápisu</span><select class="input" name="external_state_${index}" required><option value="revocation_pending">Odvolání neověřeno · předání čeká</option><option value="verified_revoked">Přístup nativně odvolán a ověřen</option><option value="uncertain_write">Nejistý zápis · nejprve dohledat</option></select></label><label class="field"><span class="lbl">Důkaz / postup a jeho výsledek</span><textarea class="input" name="external_evidence_${index}" required maxlength="4000" placeholder="Kdo, kdy a kde ověřil revokaci nebo jaký zápis čeká na dohledání. Žádné credentials."></textarea></label></fieldset>`).join('') || '<label class="check"><input type="checkbox" name="native_only" required><span>Ověřil/a jsem inventář: předávané cesty mají pouze nativně kontrolovaný Pneu přístup. Žádná externí admin session ani nejistý externí zápis nezůstává mimo tento review.</span></label>'}</div><label class="check"><input type="checkbox" name="reviewed" required><span>Přezkoumal/a jsem A, B, přesnou epoch a rulebook, otevřené případy, platné souhlasy a skutečný stav přístupů.</span></label><div><button class="btn btn-green">Připravit review předání</button></div></form>` : '<p class="empty">Předání potřebuje aktivního agenta A, aktivní rulebook a samostatné připojení B. Kandidát musí doložit schopnosti.</p>'}</section><section class="surface"><h2>Uložená předání</h2><ul class="list">${handoffs.map(item => `<li><div class="section-head"><strong class="code">${esc(item.id)}</strong>${chip(item.state)}</div>${fields([['Z agenta A', `<span class="code">${esc(item.source_id || item.source_connection_id)}</span>`], ['Na agenta B', `<span class="code">${esc(item.target_id || item.target_connection_id)}</span>`], ['Očekávaná epoch', esc(item.expected_epoch)], ['Rulebook hash', `<span class="code">${esc(item.rulebook_hash)}</span>`]])}<ul class="list">${list(item.external_access || parsed(item.external_json, [])).map(access => `<li><strong>${esc(access.system_id)}</strong> ${chip(access.state)}<p class="small">${esc(access.evidence)}</p></li>`).join('')}</ul>${item.state === 'prepared' ? `<form class="inline-form" data-form="handover-commit" data-handoff="${esc(item.id)}"><label class="check"><input name="reviewed" type="checkbox" required><span>Potvrzuji toto uložené předání. B převezme stejné případy a platné souhlasy; Handle odvolá řízená oprávnění A a zvýší epoch.</span></label><div><button class="btn btn-green">Potvrdit předání</button></div></form>` : item.state !== 'committed' ? '<p class="small mute">Předání není dokončeno. Dořešte revokaci/reconciliation a připravte nový review s aktuálními důkazy.</p>' : ''}</li>`).join('') || '<li class="empty">Žádné uložené předání.</li>'}</ul></section>`;
}
main.addEventListener('change', event => { if (event.target.id === 'business-select') { state.businessId = event.target.value; render(); } });
document.addEventListener('click', async event => {
  const button = event.target.closest('button'); if (!button || state.busy) return;
  if (button.dataset.tab) { state.tab = button.dataset.tab; render(); main.focus(); }
  if (button.dataset.auth) { state.authMode = button.dataset.auth; render(); }
  if (button.dataset.action === 'refresh') await load();
  if (button.dataset.action === 'logout') { state.busy = true; try { await api('/owner/logout', {}); state.owner = null; state.csrf = ''; state.dashboard = { businesses: [], requests: [] }; render(); feedback('Odhlášeno z lidské Handle session.'); } catch (error) { feedback(error.message, true); } finally { state.busy = false; } }
});
main.addEventListener('submit', async event => {
  const form = event.target.closest('form[data-form]'); if (!form) return; event.preventDefault(); if (state.busy) return;
  const kind = form.dataset.form, data = new FormData(form), currentBusiness = business();
  const checkedScopes = data.getAll('scopes');
  const submitter = event.submitter;
  if (kind === 'consent' && submitter?.value === 'rejected' && !data.get('user_code')) { feedback('Pro zamítnutí zadejte kód žádosti od agenta.', true); return; }
  state.busy = true;
  const buttons = [...form.querySelectorAll('button')]; buttons.forEach(button => button.disabled = true);
  try {
    let message = 'Změna byla uložena.', rotatedAccess = null;
    if (kind === 'login' || kind === 'signup') {
      const account = { email: data.get('email'), password: data.get('password'), ...(kind === 'signup' ? { setup_secret: data.get('setup_secret') } : {}) };
      form.querySelectorAll('input[type=password], input[name=setup_secret]').forEach(input => input.value = '');
      await api(`/owner/${kind}`, account); account.password = ''; if ('setup_secret' in account) account.setup_secret = '';
      message = kind === 'signup' ? 'Lidský účet Handle byl vytvořen.' : 'Přihlášeno do Handle.';
    } else if (kind === 'consent') {
      await api(`/owner/onboarding/${encodeURIComponent(form.dataset.request)}/decide`, { user_code: data.get('user_code'), decision: submitter?.value || 'approved', scopes: checkedScopes }); message = submitter?.value === 'rejected' ? 'Žádost byla zamítnuta.' : 'Auditní připojení schváleno. Agent může dokončit výměnu vlastního credentialu.';
    } else if (!currentBusiness) throw new Error('Firma již není dostupná. Obnovte přehled.');
    else if (kind === 'answer') { await api(ownerPath(currentBusiness, `questions/${encodeURIComponent(form.dataset.version)}/${encodeURIComponent(form.dataset.question)}/answer`), { answer: data.get('answer'), kind: data.get('kind'), scope: data.get('scope'), ...(data.get('valid_until') ? { valid_until: new Date(String(data.get('valid_until'))).toISOString() } : {}) }); message = 'Odpověď uložena jako lidský zdroj. Agent musí zpracovat dotčená pravidla.'; }
    else if (kind === 'activate') { await api(ownerPath(currentBusiness, `rulebooks/${encodeURIComponent(form.dataset.version)}/activate`), { payload_hash: form.dataset.hash }); message = `Aktivována přesná verze ${form.dataset.version}. Provozní a publication granty zůstávají samostatné.`; }
    else if (kind === 'approval') { await api(ownerPath(currentBusiness, `approvals/${encodeURIComponent(form.dataset.approval)}/decide`), { decision: submitter?.value }); message = 'Rozhodnutí pro přesnou nabídku bylo uloženo. Agent může načíst stav.'; }
    else if (kind === 'grant') { await api(ownerPath(currentBusiness, `connections/${encodeURIComponent(form.dataset.connection)}/authorize-operation`), { scopes: checkedScopes, expected_epoch: currentBusiness.execution_epoch }); message = 'Provozní grant byl serverem ověřen a uložen.'; }
    else if (kind === 'revoke') { await api(ownerPath(currentBusiness, `connections/${encodeURIComponent(form.dataset.connection)}/revoke`), {}); message = 'Handle připojení odvoláno. Nezávislé externí sessions je nutné ověřit samostatně.'; }
    else if (kind === 'legacy-revoke') { rotatedAccess = await api(ownerPath(currentBusiness, 'legacy-access/revoke'), { username: data.get('username') }); message = `Legacy účet ${data.get('username')} byl skutečně rotován; sessions zrušeny. Výsledek zahrňte do předání.`; }
    else if (kind === 'handover') {
      const externalAccess = [...form.querySelectorAll('[data-external-system]')].map((fieldset, index) => ({ system_id: fieldset.dataset.externalSystem, state: data.get(`external_state_${index}`), evidence: data.get(`external_evidence_${index}`) }));
      const result = await api(ownerPath(currentBusiness, 'handoffs'), { source_connection_id: currentBusiness.active_connection_id, target_connection_id: data.get('target_connection_id'), expected_epoch: currentBusiness.execution_epoch, rulebook_hash: activeRulebook(currentBusiness)?.payload_hash, external_access: externalAccess }); message = result.state === 'prepared' ? 'Review předání je připraven. Zkontrolujte jej a zvlášť potvrďte commit.' : 'Review uložen. Externí revokace nebo nejistý zápis zatím brání dokončení.';
    } else if (kind === 'handover-commit') { await api(ownerPath(currentBusiness, `handoffs/${encodeURIComponent(form.dataset.handoff)}/commit`), {}); message = 'Předání bylo serverem potvrzeno. Obnovena aktuální autorita a execution epoch.'; }
    await load(); feedback(message);
    if (rotatedAccess?.replacement_password) {
      const dialog = document.createElement('dialog'); dialog.className = 'access-dialog'; dialog.setAttribute('aria-labelledby', 'access-title');
      dialog.innerHTML = '<h2 id="access-title">Nový legacy přístup · pouze jednou</h2><p>Heslo bezpečně převezměte. Nepředávejte je původnímu agentovi A a nevkládejte je do auditu ani chatu.</p><label class="field"><span class="lbl">Nové heslo</span><input class="input code-input" type="password" readonly autocomplete="off"></label><button class="btn btn-line btn-sm" type="button" data-show-password>Zobrazit / skrýt</button><p class="small" data-evidence></p><form method="dialog"><button class="btn btn-green">Převzato, vymazat z obrazovky</button></form>';
      const password = dialog.querySelector('input'); password.value = rotatedAccess.replacement_password; rotatedAccess.replacement_password = '';
      dialog.querySelector('[data-evidence]').textContent = rotatedAccess.evidence || 'Revokace byla ověřena backendem.';
      dialog.querySelector('[data-show-password]').addEventListener('click', () => password.type = password.type === 'password' ? 'text' : 'password');
      dialog.addEventListener('close', () => { password.value = ''; dialog.remove(); }); document.body.append(dialog); dialog.showModal();
    }
  } catch (error) { feedback(error.message, true); }
  finally { state.busy = false; buttons.forEach(button => button.disabled = false); }
});
await load();
